# One edge per DISTINCT k-mer: with deep coverage the same genomic
# k-mer appears in many overlapping reads, and counting every
# occurrence would multiply edges ~30x and destroy degree balance.
# Per-read abundance is tracked separately as coverage.
self.edges = Counter()      # {(prefix, suffix): distinct-kmer count}
self.coverage = Counter()   # {(prefix, suffix): read-level abundance}
seen = set()
for read in reads:
    for kmer in kmers(read, k):
        prefix, suffix = kmer[:-1], kmer[1:]
        assert len(prefix) == self.node_k
        pair = (prefix, suffix)
        self.coverage[pair] += 1
        if kmer not in seen:
            seen.add(kmer)
            self.edges[pair] += 1

